#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int n, countTotal, prefixSum[15], result;
vector<int> data[15];

void generateSequences(int depth, int currentNumber);
void processSequences(int x);

int main() {
    cin >> n;
    generateSequences(0, 0);
    for (int i = 0; i <= 7; i++) {
        sort(data[i].begin(), data[i].end());
    }
    countTotal = 0;
    for (int i = 1; i <= 9; i++) {
