    }
    cout << result << "\n";
    return 0;
}

void generateSequences(int depth, int num) {
    if (depth == 7) return;
    countTotal++;
    int val = ((countTotal - num) % 998244353 + 998244353) % 998244353;
    data[depth].push_back(val);
    prefixSum[depth] = (prefixSum[depth] + val) % 1000000007;
    for (int digit = 0; digit <= 9; digit++) {
        generateSequences(depth + 1, num * 10 + digit);
    }
}

void processSequences(int x) {
    if (x > n) return;
    if (x * 1000000 + 999999 <= n && x * 10 * 1000000 > n) {
        int currentCount = countTotal;
        for (int i = 0, factor = 1; i <= 6; i++, factor *= 10) {
            int sizeVec = data[i].size();
            int diffVal = ((currentCount - x * factor) % 998244353 + 998244353) % 998244353;
            int position = (int)(lower_bound(data[i].begin(), data[i].end(), 1000000000 - diffVal) - data[i].begin());
            result = (result + diffVal * sizeVec + prefixSum[i]) % 1000000007;
            result = (result - 998244353 * (sizeVec - position) % 1000000007 + 1000000007) % 1000000007;
            countTotal += sizeVec;
        }
        return;
    }
    countTotal++;
    result = (result + ((countTotal - x) % 998244353 + 998244353) % 998244353) % 1000000007;
    for (int i = 0; i <= 9; i++) {
        processSequences(x * 10 + i);
    }
}
